const readRoles = new Set(['super-admin', 'sales-supervisor', 'salesperson'])
const manageRoles = new Set(['super-admin', 'sales-supervisor'])
const allWriteRoles = new Set(['super-admin', 'sales-supervisor', 'salesperson'])
const stageProbability: Record<OpportunityStage, number> = { lead: 10, qualified: 30, proposal: 50, negotiation: 70, won: 100, lost: 0 }

function read(actor: CustomerActor): void { if (!readRoles.has(actor.role)) throw new CustomerDomainError('PERMISSION_DENIED', '当前角色不可访问客户运营') }
function write(actor: CustomerActor): void { if (!allWriteRoles.has(actor.role)) throw new CustomerDomainError('PERMISSION_DENIED', '当前角色不可修改客户运营') }
function manage(actor: CustomerActor): void { if (!manageRoles.has(actor.role)) throw new CustomerDomainError('PERMISSION_DENIED', '当前角色不可管理公海规则或分配') }
function customer(state: CustomerFeatureState, id: EntityId) { const value = state.customers.find((item) => item.id === id); if (!value) throw new CustomerDomainError('NOT_FOUND', '客户不存在'); return value }
function page<T>(items: T[], pageNumber = 1, pageSize = 30): PageResult<T> { const page = Math.max(1, pageNumber); return { items: items.slice((page - 1) * pageSize, page * pageSize), total: items.length, page, pageSize } }
function day(value: string): string { return value.slice(0, 10) }

